// Énergie, eau et accès réseau : démonstration par habitat, aucune connexion réelle.
const ecoHomes=[...Array.from({length:10},(_,i)=>({id:'C'+String(i+1).padStart(2,'0'),name:'Container C'+String(i+1).padStart(2,'0')+' · '+(i<8?'Maison en L '+(Math.floor(i/2)+1):'Maison du domaine')})),{id:'CAB',name:'Cabane des sous-bois'},{id:'PER',name:'Cabane perchée'},{id:'TINY',name:'Tiny house du verger'},{id:'LOD',name:'Lodge des jardins'}];
function ecoInit(){state.ecoV9??={};for(const [i,h] of ecoHomes.entries())state.ecoV9[h.id]??={litres:650,capacity:1000,collected:0,used:0,logs:[],azimuth:0,tilt:15,shade:10,wifiPrivate:true,wifiGuest:true,accessCode:null};}
ecoInit();save();let ecoSelected='C01',ecoTab='solaire';
function ecoCurrent(){ecoInit();return state.ecoV9[ecoSelected]}
function ecoName(){return ecoHomes.find(h=>h.id===ecoSelected).name}
function solarScore(d){const orientation=(Math.cos(d.azimuth*Math.PI/180)+1)/2,tilt=Math.max(0,1-Math.abs(d.tilt-15)/90),shade=1-d.shade/100;return Math.round(orientation*tilt*shade*100)}
function solarIllustration(d){let slope=10+d.tilt*.8,shift=d.azimuth/6;return `<svg class="solar-view" viewBox="0 0 620 300" role="img" aria-label="Vue conceptuelle d’un toit avec panneaux inclinés de ${d.tilt} degrés, orientation ${d.azimuth} degrés et ${d.shade} pour cent d’ombrage"><rect width="620" height="300" fill="#e7eddd"/><circle cx="480" cy="53" r="29" fill="#ebce81"/><path d="m459 79-76 69m64-49-50 47m76-62-65 72" stroke="#d9b459" stroke-width="2" stroke-dasharray="6 7"/><path d="m130 149 176-80 191 88-175 87Z" fill="#b5bfaa"/><path d="m130 149 192 95v42l-192-94Z" fill="#b18d61"/><path d="m322 244 175-87v42l-175 87Z" fill="#8d7958"/>${Array.from({length:4},(_,i)=>{let x=160+i*62+shift,y=143+i*5;return `<path d="m${x} ${y} 43-24 45 ${18-slope/2} -43 26Z" fill="#315b68" stroke="#a5c3bd" stroke-width="1.5"/><path d="m${x+22} ${y-12} 45 ${18-slope/2}" stroke="#86a9a9"/>`}).join('')}<text x="30" y="35" fill="#537047" font-family="sans-serif" font-size="12">VUE D’INTENTION · CONFIGURATION SOLAIRE</text><text x="30" y="275" fill="#6f805f" font-family="sans-serif" font-size="11">Orientation et pente illustratives · aucune étude de rendement</text></svg>`}
function ecoView(){ecoInit();return heading('Le Domaine, connecté aux ressources.','Panneaux solaires, litres d’eau et réseaux Wi-Fi suivis par habitat.',`<a class="btn light" href="#ville">Voir les équipements en 3D ↗</a>`)+`<div class="travel-demo">Simulation locale · Aucun panneau, compteur, routeur ni capteur réel connecté. Les valeurs ne sont pas des mesures du Domaine.</div><section class="eco-select"><div><label for="eco-home">Choisir un habitat</label><select id="eco-home" onchange="ecoSelected=this.value;render()">${ecoHomes.map(h=>`<option value="${h.id}" ${ecoSelected===h.id?'selected':''}>${h.name}</option>`).join('')}</select></div><p>10 containers d’habitation, répartis en 5 maisons en L, plus les hébergements alternatifs de présentation. Le laboratoire est séparé.</p></section><div class="eco-tabs">${[['solaire','☀ Solaire & optimisation'],['eau','◉ Eau & litres'],['wifi','≋ Wi-Fi public / privé']].map(([id,label])=>`<button aria-pressed="${ecoTab===id}" onclick="ecoTab='${id}';render()">${label}</button>`).join('')}</div>${ecoTab==='solaire'?ecoSolar():ecoTab==='eau'?ecoWater():ecoWifi()}`}
function ecoSolar(){const d=ecoCurrent(),score=solarScore(d);return `<div class="eco-grid"><section class="panel"><div class="paneltop"><h2>${ecoName()}</h2><span class="mini">Configuration de démonstration</span></div><div id="solar-drawing">${solarIllustration(d)}</div><div class="eco-kpis"><div><small>Panneaux imaginés</small><b>4 × 400 Wc</b><span>Hypothèse illustrative</span></div><div><small>Puissance nominale</small><b>1,6 kWc</b><span>Scénario, pas une puissance mesurée</span></div><div><small>Indice pédagogique</small><b id="solar-score">${score} / 100</b><span>Ne représente pas un rendement</span></div></div><p class="smallnote">Le schéma et l’indice servent à comparer des réglages. La météo, les ombres réelles, les équipements et le lieu d’implantation ne sont pas modélisés.</p></section><section class="panel"><h2>Explorer une optimisation</h2><label for="solar-orientation">Orientation relative : <b id="azimuth-val">${d.azimuth}°</b></label><input id="solar-orientation" type="range" min="-180" max="180" step="5" value="${d.azimuth}" oninput="solarAdjust('azimuth',this.value)"><label for="solar-tilt">Inclinaison : <b id="tilt-val">${d.tilt}°</b></label><input id="solar-tilt" type="range" min="0" max="60" step="1" value="${d.tilt}" oninput="solarAdjust('tilt',this.value)"><label for="solar-shade">Ombrage de scénario : <b id="shade-val">${d.shade}%</b></label><input id="solar-shade" type="range" min="0" max="80" value="${d.shade}" oninput="solarAdjust('shade',this.value)"><button class="btn light" onclick="solarPreset()">Comparer au réglage de référence</button><div class="notice">Référence pédagogique arbitraire : 0° relatif, pente 15°, ombre 0 %. Ce n’est pas une recommandation pour le terrain. Une optimisation réelle nécessite une étude du site.</div></section></div>`}
function solarAdjust(key,v){const d=ecoCurrent();d[key]=Number(v);save();$('#azimuth-val').textContent=d.azimuth+'°';$('#tilt-val').textContent=d.tilt+'°';$('#shade-val').textContent=d.shade+'%';$('#solar-score').textContent=solarScore(d)+' / 100';$('#solar-drawing').innerHTML=solarIllustration(d)}
function solarPreset(){Object.assign(ecoCurrent(),{azimuth:0,tilt:15,shade:0});save();render();toast('Réglage de référence appliqué à la simulation.')}
function ecoWater(){const d=ecoCurrent();return `<div class="eco-grid"><section class="panel"><div class="paneltop"><h2>La réserve de ${ecoSelected}</h2><span class="mini">Capteur de litres simulé</span></div><div class="tank-scene"><div class="eco-tank"><div style="height:${d.litres/d.capacity*100}%"></div><b>${d.litres}<small>litres simulés</small></b></div><div class="tank-flow"><span>Toiture</span><i>↓ Gouttière & filtre</i><span>Cuve · ${d.capacity} L</span><i>↓ Compteur de volume</i><span>Usages non alimentaires à définir</span></div></div><div class="eco-kpis"><div><small>Volume disponible</small><b>${d.litres} L</b></div><div><small>Apports simulés</small><b>${d.collected} L</b></div><div><small>Utilisation simulée</small><b>${d.used} L</b></div></div>${d.litres<200?'<div class="notice">Alerte de scénario : niveau de cuve inférieur à 20 %.</div>':''}<p class="smallnote">Niveau initial fictif : 650 L. Aucun débitmètre ni capteur de niveau connecté. Le compteur affiche des volumes en litres, sans mesurer de débit réel.</p></section><section class="panel"><h2>Tester les remontées dans l’application</h2><p class="sub" style="margin-top:15px">Un événement met à jour le niveau, le total de litres et le journal de cet habitat.</p><div class="eco-actions"><button class="btn" onclick="waterEvent(100)">Simuler une collecte de 100 L</button><button class="btn light" onclick="waterEvent(-20)">Simuler une utilisation de 20 L</button></div><label for="water-manual">Saisir un niveau de démonstration (0 à ${d.capacity} L)</label><form onsubmit="event.preventDefault();setWaterDemo(this.litres.value)"><input type="number" id="water-manual" name="litres" required min="0" max="${d.capacity}" step="1" value="${d.litres}"><button class="btn light" style="margin-top:12px">Enregistrer le niveau fictif</button></form><div class="notice">Récupération de pluie conceptuelle : aucun usage potable n’est validé. Cuve, filtration, réseaux et usages réels restent à définir.</div></section></div><section class="panel"><h2>Journal des litres · ${ecoSelected}</h2>${d.logs.map(e=>`<div class="eco-log"><b>${e.kind}</b><span>${e.amount>0?'+':''}${e.amount} L · niveau ${e.level} L</span><small>${new Date(e.at).toLocaleString('fr-FR',{timeZone:'America/Martinique'})} · simulation</small></div>`).join('')||'<p class="smallnote">Aucun événement simulé. Testez une collecte ou une utilisation.</p>'}</section>`}
function waterEvent(amount){const d=ecoCurrent(),actual=amount>0?Math.min(amount,d.capacity-d.litres):-Math.min(-amount,d.litres);if(!actual){toast(amount>0?'Cuve de démonstration pleine.':'Cuve de démonstration vide.');return}d.litres+=actual;if(actual>0)d.collected+=actual;else d.used-=actual;d.logs.unshift({kind:actual>0?'Collecte fictive':'Utilisation fictive',amount:actual,level:d.litres,at:new Date().toISOString()});save();render();toast('Volume mis à jour dans l’application de démonstration.')}
function setWaterDemo(v){const n=Number(v),d=ecoCurrent();if(!Number.isInteger(n)||n<0||n>d.capacity)return;const amount=n-d.litres;d.litres=n;d.logs.unshift({kind:'Niveau saisi · fictif',amount,level:n,at:new Date().toISOString()});save();render();toast('Niveau de démonstration enregistré.')}
function ecoWifi(){const d=ecoCurrent();return `<div class="eco-grid"><section class="panel"><div class="eyebrow">ACCÈS PARTAGÉ</div><h2 style="margin-top:18px">Wi-Fi public du Domaine</h2><div class="wifi-symbol">≋</div><h3>Domaine-Visiteurs</h3><p class="sub">Un accès invité proposé pour la place, le marché, l’accueil et les espaces communs.</p><button class="eco-switch" role="switch" aria-checked="${d.wifiGuest}" onclick="toggleEcoWifi('wifiGuest')">${d.wifiGuest?'✓ Activé dans la démo':'○ Désactivé dans la démo'}</button><p class="smallnote">État de scénario pour cet habitat. Aucun routeur public n’est configuré ni détecté.</p></section><section class="panel"><div class="eyebrow">ACCÈS RÉSIDENT</div><h2 style="margin-top:18px">Wi-Fi privé de l’habitat</h2><div class="wifi-symbol">⌂</div><h3>Domaine-${ecoSelected}-Prive</h3><p class="sub">Un réseau distinct envisagé pour chaque habitat, avec un accès réservé aux occupants.</p><button class="eco-switch" role="switch" aria-checked="${d.wifiPrivate}" onclick="toggleEcoWifi('wifiPrivate')">${d.wifiPrivate?'✓ Activé dans la démo':'○ Désactivé dans la démo'}</button><div class="eco-actions"><button class="btn light" onclick="wifiCode()">Créer un code invité fictif</button></div>${d.accessCode?`<div class="wifi-code"><small>Code de démonstration · sans accès réseau réel</small><b>${d.accessCode}</b></div>`:''}</section></div><section class="panel"><h2>Une séparation à prévoir dès la conception.</h2><div class="grid3" style="margin-top:20px">${[['Visiteurs','Un portail invité pour les zones communes.'],['Occupants','Un réseau privé propre à chaque habitat.'],['Équipements','Un réseau technique séparé envisagé pour les compteurs et capteurs.']].map(x=>`<div><h3>${x[0]}</h3><p class="sub">${x[1]}</p></div>`).join('')}</div><p class="smallnote">Architecture proposée, à configurer et tester sur le matériel réel. Aucun isolement, chiffrement ou débit n’est attesté par cette maquette.</p></section>`}
function toggleEcoWifi(key){ecoCurrent()[key]=!ecoCurrent()[key];save();render()}
function wifiCode(){ecoCurrent().accessCode='DEMO-'+ecoSelected+'-'+Math.floor(1000+Math.random()*9000);save();render();toast('Code fictif créé. Il ne permet de rejoindre aucun réseau.')}
function openEco(id,tab='solaire'){if(ecoHomes.some(h=>h.id===id))ecoSelected=id;ecoTab=tab;$('#modal')?.close();if(location.hash==='#ressources')render();else location.hash='#ressources'}
function stayEcoId(id){return {luxe:'C09',container:'C01',cabane:'CAB',perchee:'PER',tiny:'TINY',lodge:'LOD'}[id]}
const detailBeforeEco=stayDetail;stayDetail=function(id){detailBeforeEco(id);if(id==='tiny'){const art=$('#modalbody .stay-detail-art');if(art)art.innerHTML='<img src="assets/tiny-house-solaire-eau.webp" alt="Visualisation d’une tiny house en bois avec panneaux solaires et cuve d’eau">'}$('#modalbody').insertAdjacentHTML('beforeend',`<div class="eco-detail-links"><button onclick="openEco('${stayEcoId(id)}','solaire')">☀ Panneaux solaires</button><button onclick="openEco('${stayEcoId(id)}','eau')">◉ Eau & litres</button><button onclick="openEco('${stayEcoId(id)}','wifi')">≋ Wi-Fi public / privé</button></div>`)};
const cardsBeforeEco=stayCards;stayCards=function(items){let html=cardsBeforeEco(items);const tiny=habitatArt('tiny');html=html.replace(tiny,'<img src="assets/tiny-house-solaire-eau.webp" alt="Visualisation d’une tiny house avec panneaux solaires et récupération d’eau">');return html};
const domaineBeforeEco=views.domaine;views.domaine=function(){return `<div class="eco-detail-links"><button onclick="openEco('C09','solaire')">☀ Optimiser les panneaux</button><button onclick="openEco('C09','eau')">◉ Suivre les litres d’eau</button><button onclick="openEco('C09','wifi')">≋ Accès Wi-Fi de la maison</button></div>`+domaineBeforeEco()};
routes.splice(routes.findIndex(r=>r[0]==='domaine')+1,0,['ressources','☀','Énergie, eau & Wi-Fi']);views.ressources=ecoView;
cityPlaces.find(p=>p.id==='habitats').desc='Quatre maisons en L composées de huit containers. Avec les deux containers de la maison du domaine, le plan comporte exactement dix containers d’habitation. Le laboratoire n’est pas inclus dans ce total.';
cityPlaces.find(p=>p.id==='habitats').short='4 maisons en L · 8 containers';
// Le container jardin désigne un volume existant du quartier : il n’ajoute pas un onzième container.
const singlePlace=cityPlaces.find(p=>p.id==='stay-container');singlePlace.x=-165;singlePlace.y=-135;
cityPlaces.push({id:'parking',name:'Le parking du Domaine',short:'Parking voitures, motos & vélos',icon:'P',label:'PARKING',x:-10,y:213,desc:'Un parking de présentation à l’entrée, séparé des circulations piétonnes : six places voitures, quatre motos et un abri pour six vélos.',stat:'6',unit:'voitures · scénario',stat2:'4 + 6',unit2:'motos et vélos',detail:'Implantation illustrative. Les dimensions, circulations et accès sont à étudier pour le terrain réel.',action:'Consulter les vélos disponibles',route:'velos'});
const cityViewBeforeEco=views.ville;views.ville=function(){return `<div class="eco-map-summary"><span><b>10</b> containers d’habitation</span><span><b>5</b> maisons en L</span><span>☀ Solaire · ◉ Cuves · ≋ Wi-Fi</span><a href="#ressources">Ouvrir le suivi des habitats ↗</a></div>`+cityViewBeforeEco()};
const resetBeforeEco=resetDemo;resetDemo=function(){resetBeforeEco();state.ecoV9={};ecoInit();save();render()};
slides.splice(3,0,{k:'LES RESSOURCES CONNECTÉES',title:'Habiter le Domaine.<br>Comprendre ses ressources.',text:'Dix containers d’habitation, cinq maisons en L. Les panneaux solaires, cuves d’eau et accès Wi-Fi sont intégrés à la présentation.',cards:[['Solaire','Des panneaux visibles en 3D et une vue de réglage pédagogique par habitat.'],['Eau','Récupération de pluie, niveau en litres, apports et utilisations simulés dans l’application.'],['Accès & mobilité','Wi-Fi public et privé envisagé par habitat. Parking voitures, motos et vélos.']]});slides.forEach((s,i)=>s.k=String(i+1).padStart(2,'0')+' · '+s.k.replace(/^\d+ · /,''));
render();
